import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"RFQ 平台","description":"","frontmatter":{"title":"RFQ 平台","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rfq-platforms.md","filePath":"quant/rfq-platforms.md","lastUpdated":1789023840000}'),E={name:"quant/rfq-platforms.md"};function c(u,a,f,B,m,A){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="rfq-平台" tabindex="-1">RFQ 平台 <a class="header-anchor" href="#rfq-平台" aria-label="Permalink to &quot;RFQ 平台&quot;">​</a></h1><div class="epigraph"><p>电子询价把「打电话问几家」收成报文：同一数量、同一方向、有限回复窗。它加快搜索，也把需求信号同时发给一圈对手；竞争与泄露是同一按钮的两面。</p><footer>—— Hendershott and Madhavan, Click or Call? Auction versus Search in the Over-the-Counter Market, Journal of Finance, 2015</footer></div><p><a href="/quant/otc-dealer-market">场外经销商</a> 把匹配写成搜索与议价。缺口是搜索被平台化之后：请求报价（RFQ）成为一类场所协议——债券、期权复杂单、大宗股票、部分外汇都在用。<a href="/quant/corporate-bond-otc">公司债 OTC 询价</a> 已从执行会计写过债券 RFQ；本课写跨品种的设计比较：RFQ、可点击指示价、语音、以及公开限价簿各解决哪一类同时性。不提供「询几家最合适」的操作清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>客户提交：工具、方向、数量、回复截止。平台把请求发给一组经销商，经销商选择回复或沉默，客户选择成交或放弃。与 <a href="/quant/lob-structure">LOB</a> 的差别是：没有公共时间优先，没有对全市场有效的深度，价格对所询数量歧视。与一对一电话的差别是：请求被标准化、可审计、可同时竞争。Hendershott 与 Madhavan（2015）把电子拍卖式询价与语音搜索对照：电子化降低搜寻摩擦，也可能改变谁愿意提交存货。问题是协议如何权衡三点——竞争（多家同时回）、泄露（需求被看见）、以及赢家诅咒（回复者知道别人也在看）。</p><p>期权复杂单已经用过 RFQ：多腿同时性靠询价网而不是靠每一种结构一张簿。股票大宗的「上楼」或电子询价是同一逻辑的尺寸维。</p><h3 id="点击成交不是变薄的-lob" tabindex="-1">点击成交不是变薄的 LOB <a class="header-anchor" href="#点击成交不是变薄的-lob" aria-label="Permalink to &quot;点击成交不是变薄的 LOB&quot;">​</a></h3><p>部分平台在 RFQ 之外展示可点击的指示性报价。深度通常只覆盖小规模，价格常常「参考」而非承诺，经销商仍可拒绝。把它当成公开 BBO，会把电子零售层当成整个 OTC。协议分层：可点击（小额即时性）、RFQ（机构目标规模）、语音（冷门、大额、复杂条款）。混成一个价差，小单的窄加价会淹没大单的搜索成本。</p><p><span class="marginnote">平台若向经销商披露「正在询几家」，竞争加剧，泄露也加剧。不披露则经销商按先验回复，加价含不确定性补偿。这是透明课在询价网上的版本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象是 RFQ 生命周期，不是打印价。状态：发送时刻、受询名单规模、回复数、最优回复相对基准偏离、成交与否、从发送到成交的时间、未成交后的机会成本。填成率与回复率是流动性一等指标。Hendershott–Madhavan 的识别靠同一资产在电子拍卖与语音之间的分流，而不是把所有 OTC 成交当同质。跨品种比较时，只比较协议特征（是否匿名、是否披露询价家数、回复是否对全市场可见），不要比较名义基点——债券与期权的经济对象不同。</p><p>赢家诅咒：若只有被选中的回复「赢」，经销商会把被捡风险写进加价。这与限价单被捡同构，只是没有公共簿上的期权金，而是写进每一条回复。</p>',12)),(e(),s(h,null,{default:r(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20RFQ%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E8%AF%A2%E4%BB%B7%E6%8A%A5%E6%96%87%22%5D%20--%3E%20Comp%5B%22%E5%A4%9A%E5%AE%B6%E5%90%8C%E6%97%B6%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20RFQ%20--%3E%20Leak%5B%22%E9%9C%80%E6%B1%82%E4%BF%A1%E5%8F%B7%E6%B3%84%E9%9C%B2%22%5D%0A%20%20Comp%20--%3E%20Tight%5B%22%E5%8A%A0%E4%BB%B7%E5%8F%AF%E8%A2%AB%E7%AB%9E%E4%BA%89%E5%8E%8B%E7%AA%84%22%5D%0A%20%20Leak%20--%3E%20Wide%5B%22%E7%9F%A5%E6%83%85%E6%BA%A2%E4%BB%B7%20%2F%20%E6%B2%89%E9%BB%98%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RFQ 把 Duffie 搜索的「随机相遇」改成「有限期的多边询价」。竞争压低加价，接近一次性密封拍卖；泄露提高逆向选择，接近把 \\(y\\) 提前告诉一圈做市商。均衡加价是两者之差。沉默也是策略：库存不对、或把你识别成知情，最优回复是不回——观测到的回复分布是被选择过的，平均加价低估未成交意图的成本。</p><p>对公开市场的反馈：经销商中标后要到对冲工具上卸库存（国债期货、CDS、标的股票）。RFQ 成交是 OTC 事件，冲击可以出现在有 LOB 的腿上。期权复杂询价已经写过这一时钟；债券与外汇同样。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各平台的匿名、披露、最小数量、是否允许 last look 式确认，差异大。把「电子化」当成单一虚拟变量，会把 RFQ 与后课的全对全混在一起。本课不覆盖如何选择受询名单以获取更好价格。下一课专写债券：电子 RFQ 普及之后，全对全能否把经销商从中心位置挪开。</p><p><span class="marginnote">回测用 RFQ 最优回复当「可成交中点」，忽略沉默与事后拒绝，会编造不存在的流动性。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFQ 是标准化的多边询价，不是慢一点的市价单，也不是公共限价簿。</li><li>竞争与泄露同在；回复率、填成、相对基准偏离才是质量。</li><li>可点击指示价、RFQ、语音是分层协议，不能合成一个价差。</li><li>问得太多则胜者诅咒加重、拒报上升；问得太少则竞争不足。</li><li>出处：Hendershott and Madhavan, <em>Journal of Finance</em>, 2015；搜寻基准见 Duffie, Gârleanu and Pedersen, <em>Econometrica</em>, 2005。</li></ul>',8))])}const q=n(E,[["render",c]]);export{F as __pageData,q as default};
